{"content":"const fs = require('fs');

function parseVarInt(buf, offset) {
  if (offset >= buf.length) {
    throw new Error('Unexpected end of data while reading VarInt');
  }
  const first = buf[offset];
  if (first < 0xfd) {
    return { value: first, size: 1 };
  }
  if (first === 0xfd) {
    if (offset + 3 > buf.length) {
      throw new Error('Unexpected end of data while reading VarInt (0xfd)');
    }
    return { value: buf.readUInt16LE(offset + 1), size: 3 };
  }
  if (first === 0xfe) {
    if (offset + 5 > buf.length) {
      throw new Error('Unexpected end of data while reading VarInt (0xfe)');
    }
    return { value: buf.readUInt32LE(offset + 1), size: 5 };
  }
  // 0xff
  if (offset + 9 > buf.length) {
    throw new Error('Unexpected end of data while reading VarInt (0xff)');
  }
  const big = buf.readBigUInt64LE(offset + 1);
  if (big > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new Error('VarInt value exceeds maximum safe integer');
  }
  return { value: Number(big), size: 9 };
}

function main() {
  const filePath = process.argv[2];
  if (!filePath) {
    console.error('Usage: node parse_tx.js <path_to_hex_file>');
    process.exit(1);
  }

  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (e) {
    console.error(`Failed to read file: ${e.message}`);
    process.exit(1);
  }

  const hex = raw.replace(/\s+/g, '').toLowerCase();

  if (hex.length === 0) {
    console.error('Empty transaction hex');
    process.exit(1);
  }
  if (hex.length % 2 !== 0) {
    console.error('Malformed hex string: odd length');
    process.exit(1);
  }
  if (!/^[0-9a-f]*$/.test(hex)) {
    console.error('Malformed hex string: invalid characters');
    process.exit(1);
  }

  let buf;
  try {
    buf = Buffer.from(hex, 'hex');
  } catch (e) {
    console.error(`Malformed hex string: ${e.message}`);
    process.exit(1);
  }

  if (buf.length < 4) {
    console.error('Incomplete transaction: missing version');
    process.exit(1);
  }

  try {
    let offset = 0;

    function need(n, what) {
      if (offset + n > buf.length) {
        throw new Error(`Incomplete transaction: ${what}`);
      }
    }

    // Version
    need(4, 'missing version');
    const version = buf.readUInt32LE(offset);
    offset += 4;

    // Input count
    const inCount = parseVarInt(buf, offset);
    offset += inCount.size;
    const inputCount = inCount.value;

    const inputs = [];
    for (let i = 0; i < inputCount; i++) {
      need(32, `input ${i}: missing txid`);
      const txidBytes = buf.subarray(offset, offset + 32);
      const txid = Buffer.from(txidBytes).reverse().toString('hex');
      offset += 32;

      need(4, `input ${i}: missing vout`);
      const vout = buf.readUInt32LE(offset);
      offset += 4;

      const slen = parseVarInt(buf, offset);
      offset += slen.size;

      need(slen.value, `input ${i}: incomplete scriptsig`);
      const scriptsig = buf.subarray(offset, offset + slen.value).toString('hex');
      offset += slen.value;

      need(4, `input ${i}: missing sequence`);
      const sequence = buf.readUInt32LE(offset);
      offset += 4;

      inputs.push({ txid, vout, scriptsig, sequence });
    }

    // Output count
    const outCount = parseVarInt(buf, offset);
    offset += outCount.size;
    const outputCount = outCount.value;

    const outputs = [];
    for (let i = 0; i < outputCount; i++) {
      need(8, `output ${i}: missing value`);
      const valueBig = buf.readBigUInt64LE(offset);
      offset += 8;
      const value =
        valueBig <= BigInt(Number.MAX_SAFE_INTEGER)
          ? Number(valueBig)
          : Number(valueBig); // JSON cannot represent BigInt; keep numeric
      // Detect precision loss for extremely large values is unavoidable in JSON numbers.

      const plen = parseVarInt(buf, offset);
      offset += plen.size;

      need(plen.value, `output ${i}: incomplete scriptpubkey`);
      const scriptpubkey = buf.subarray(offset, offset + plen.value).toString('hex');
      offset += plen.value;

      outputs.push({ value, scriptpubkey });
    }

    // Locktime
    need(4, 'missing locktime');
    const locktime = buf.readUInt32LE(offset);
    offset += 4;

    if (offset !== buf.length) {
      throw new Error(`Malformed transaction: ${buf.length - offset} trailing byte(s)`);
    }

    const result = {
      version,
      input_count: inputCount,
      inputs,
      output_count: outputCount,
      outputs,
      locktime,
    };

    process.stdout.write(JSON.stringify(result));
    process.stdout.write('\n');
  } catch (e) {
    console.error(`Failed to parse transaction: ${e.message}`);
    process.exit(1);
  }
}

main();
